// Bearing Live v0.10 - built-in PUBLIC-DOMAIN hymn library (read-only, bundled in the app; generated by tools/gen_hymns.py).
// Users browse/search it and COPY a hymn into their own library to edit/arrange. There is no public pool of user charts:
// every user's library is private to them (and their band via the leader's sync).
#pragma once
#include "model/Song.h"
#include <string>
#include <vector>

namespace wr {
struct Hymn {
    std::string id, title, textAuthor; int textYear = 0; std::string tune, tuneSource; int tuneYear = 0;
    std::string pdBasis;     // why it's public domain (also embedded in the ChordPro as {meta: public_domain ...})
    std::string chordPro;    // complete chart: title, artist, key, tempo, time, sections, chords
};
const std::vector<Hymn>& hymnLibrary();
const Hymn* findHymn (const std::string& id);
// Case/accent-insensitive search over title, first line, author, tune and lyrics. Ranked: title start > title > first line >
// author/tune > lyrics. Empty query = whole library alphabetically.
std::vector<const Hymn*> searchHymns (const std::string& query);
std::string hymnFirstLine (const Hymn&);
Chart hymnChart (const Hymn&);
// Copies a hymn into the user's library as a normal, editable song (new id "<hymn-id>", "-2", ... if taken). "" if unknown id.
std::string copyHymnToLibrary (Library& lib, const std::string& hymnId);
} // namespace wr
